head.b:skin:
/*
  Theme Name: Singh Creative Studio Premium Light Portfolio
  Founder: MUKESH SINGH
  Tagline: Ideas Made Visible.
*/
:root {
  --bg: #FFFFFF;
  --panel: #F5F8FF;
  --card: #FFFFFF;
  --primary: #4F46E5;
  --electric: #2563EB;
  --cyan: #06B6D4;
  --violet: #8B5CF6;
  --text: #111827;
  --muted: #64748B;
  --border: #E5EAF3;
  --glow: rgba(79, 70, 229, 0.14);
  --shadow-sm: 0 4px 12px rgba(17, 24, 39, 0.04);
  --shadow-md: 0 12px 28px rgba(79, 70, 229, 0.08);
  --shadow-lg: 0 20px 48px rgba(79, 70, 229, 0.12);
  --max: 1280px;
  --font-heading: 'Space Grotesk', sans-serif;
  --font-body: 'DM Sans', sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
  font-size: 16px;
  -webkit-tap-highlight-color: transparent;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  line-height: 1.6;
  overflow-x: hidden;
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

button, input, select, textarea {
  font-family: inherit;
  font-size: inherit;
  background: none;
  border: none;
  color: inherit;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

svg {
  max-width: 100%;
}

.container {
  width: min(var(--max), calc(100% - 48px));
  margin-left: auto;
  margin-right: auto;
}

.display {
  font-family: var(--font-heading);
  letter-spacing: -0.05em;
}

.gradient-text {
  background: linear-gradient(135deg, #4F46E5 0%, #2563EB 50%, #06B6D4 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.eyebrow {
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.eyebrow::before {
  content: '';
  width: 24px;
  height: 2px;
  background: var(--primary);
  border-radius: 2px;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 18px;
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--primary);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  background: #FFFFFF;
  box-shadow: var(--shadow-sm);
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  flex-shrink: 0;
}

/* Buttons & Interactive Elements */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 28px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: -0.01em;
  transition: all 0.28s cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
  white-space: nowrap;
  border: 1px solid transparent;
}

.btn:hover {
  transform: translateY(-3px);
}

.btn-primary {
  background: linear-gradient(135deg, #4F46E5, #2563EB, #06B6D4);
  color: #FFFFFF;
  box-shadow: 0 8px 24px rgba(79, 70, 229, 0.25);
}

.btn-primary:hover {
  box-shadow: 0 12px 32px rgba(79, 70, 229, 0.4);
  color: #FFFFFF;
}

.btn-ghost {
  border-color: var(--primary);
  background: #FFFFFF;
  color: var(--primary);
  box-shadow: var(--shadow-sm);
}

.btn-ghost:hover {
  background: rgba(79, 70, 229, 0.06);
  border-color: var(--electric);
  color: var(--electric);
}

/* Circular Icon Buttons */
.btn-icon {
  width: 46px;
  height: 46px;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: #FFFFFF;
  color: var(--text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: all 0.25s ease;
  flex-shrink: 0;
}

.btn-icon svg {
  width: 20px;
  height: 20px;
  display: block;
}

.btn-icon svg line,
.btn-icon svg path,
.btn-icon svg circle,
.btn-icon svg rect,
.btn-icon svg polygon,
.btn-icon svg polyline {
  fill: none;
  stroke: #111827 !important;
  stroke-width: 2.2px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.btn-icon.active svg line,
.btn-icon.active svg path,
.btn-icon.active svg circle,
.btn-icon.active svg rect,
.btn-icon.active svg polygon,
.btn-icon.active svg polyline {
  stroke: #FFFFFF !important;
}

.btn-icon:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(79, 70, 229, 0.05);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-icon.active {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  color: #FFFFFF;
  border-color: transparent;
}

/* Topline Accent Bar */
.topline {
  height: 3px;
  background: linear-gradient(90deg, var(--primary), var(--cyan), var(--violet));
  position: relative;
  z-index: 1000;
}

/* Light Intro Screen with Cinematic Transition */
.intro {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  padding: 24px;
  background: radial-gradient(ellipse at 50% 35%, rgba(79, 70, 229, 0.12), transparent 60%), #FFFFFF;
  transition: opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1), transform 0.8s cubic-bezier(0.22, 1, 0.36, 1), visibility 0.8s;
  overflow: hidden;
}

.intro-glow-bg {
  position: absolute;
  inset: -50%;
  background: radial-gradient(circle at 50% 50%, rgba(79, 70, 229, 0.35), rgba(37, 99, 235, 0.2), rgba(6, 182, 212, 0.15), transparent 70%);
  opacity: 0;
  transform: scale(0.3);
  transition: transform 1.1s cubic-bezier(0.22, 1, 0.36, 1), opacity 1.1s cubic-bezier(0.22, 1, 0.36, 1);
  pointer-events: none;
  z-index: 1;
}

.intro.transitioning .intro-glow-bg {
  opacity: 1;
  transform: scale(1.8);
}

.intro.hidden {
  opacity: 0;
  transform: scale(1.04);
  visibility: hidden;
  pointer-events: none;
}

.intro-inner {
  text-align: center;
  max-width: 680px;
  position: relative;
  z-index: 2;
  transition: transform 0.8s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.intro.transitioning .intro-inner {
  transform: scale(1.06) translateY(-12px);
  opacity: 0;
}

#enterStudio {
  position: relative;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.3s cubic-bezier(0.22, 1, 0.36, 1), background 0.3s ease;
}

#enterStudio.active-cta {
  transform: scale(0.95);
  box-shadow: 0 0 35px rgba(79, 70, 229, 0.6), 0 0 60px rgba(6, 182, 212, 0.4);
}

body.intro-dismissed .header,
body.intro-dismissed .hero-copy,
body.intro-dismissed .visual-wrap {
  animation: heroEntrance 1.1s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@keyframes heroEntrance {
  0% {
    opacity: 0;
    transform: translateY(20px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.logo-monogram {
  width: 80px;
  height: 80px;
  border-radius: 24px;
  margin: 0 auto 24px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--primary) 0%, var(--electric) 50%, var(--cyan) 100%);
  color: #FFFFFF;
  font: 800 2.6rem var(--font-heading);
  box-shadow: 0 12px 36px rgba(79, 70, 229, 0.3);
  transform: rotate(-6deg);
  transition: transform 0.4s ease;
}

.logo-monogram:hover {
  transform: rotate(0deg) scale(1.05);
}

.logo-monogram span {
  transform: rotate(6deg);
  display: block;
}

.intro h1 {
  font: 800 clamp(2.4rem, 7.5vw, 4.8rem) / 1.02 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 0;
  color: var(--text);
}

.intro .founder {
  font-size: 0.8rem;
  font-weight: 800;
  letter-spacing: 0.35em;
  color: var(--primary);
  margin: 18px 0 6px;
  text-transform: uppercase;
}

.intro .tagline {
  color: var(--muted);
  font-size: 1.1rem;
  margin: 0 0 32px;
}

.intro-orbit {
  position: absolute;
  width: min(85vw, 650px);
  height: min(85vw, 650px);
  border: 1px solid rgba(79, 70, 229, 0.12);
  border-radius: 50%;
  pointer-events: none;
  z-index: 1;
}

.intro-orbit::after {
  content: '';
  position: absolute;
  inset: 12%;
  border: 1px dashed rgba(6, 182, 212, 0.25);
  border-radius: 50%;
  animation: spin 35s linear infinite;
}

/* Main Header & Navigation */
.header {
  position: sticky;
  top: 0;
  z-index: 900;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border);
}

.nav {
  height: 80px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font: 700 1.15rem var(--font-heading);
  letter-spacing: -0.03em;
  color: var(--text);
  transition: opacity 0.2s;
}

.brand:hover {
  opacity: 0.85;
}

.brand-icon {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--primary), var(--cyan));
  color: #FFFFFF;
  font: 800 1.3rem var(--font-heading);
  box-shadow: 0 4px 16px rgba(79, 70, 229, 0.2);
}

.navlinks {
  display: flex;
  align-items: center;
  gap: 32px;
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 600;
}

.navlinks a {
  transition: color 0.2s ease;
}

.navlinks a:hover {
  color: var(--primary);
}

.navlinks .navcta {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  color: #FFFFFF;
  padding: 10px 22px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 0.88rem;
  box-shadow: 0 4px 14px rgba(79, 70, 229, 0.2);
  transition: transform 0.2s, box-shadow 0.2s;
}

.navlinks .navcta:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(79, 70, 229, 0.35);
  color: #FFFFFF;
}

.menu-toggle {
  display: none;
}

.menu-toggle svg {
  display: block;
  width: 22px;
  height: 22px;
  stroke: var(--text-main);
  stroke-width: 2.5;
  stroke-linecap: round;
}

/* Light Hero Section */
.hero {
  position: relative;
  padding: 90px 0 75px;
  overflow: hidden;
  background: radial-gradient(circle at 80% 20%, rgba(79, 70, 229, 0.06) 0%, transparent 60%), #FFFFFF;
}

.hero::before {
  content: '';
  position: absolute;
  width: 550px;
  height: 550px;
  right: -200px;
  top: -150px;
  background: rgba(79, 70, 229, 0.08);
  filter: blur(120px);
  border-radius: 50%;
  pointer-events: none;
}

.hero-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr 1.05fr;
  gap: 48px;
  align-items: center;
}

.hero-copy h2 {
  font: 800 clamp(3.2rem, 5.8vw, 5.8rem) / 0.98 var(--font-heading);
  letter-spacing: -0.065em;
  margin: 22px 0;
  color: var(--text);
}

.hero-copy p {
  color: var(--muted);
  max-width: 520px;
  font-size: 1.08rem;
  line-height: 1.65;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 32px;
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 36px;
  color: var(--muted);
  font-size: 0.85rem;
}

.hero-meta b {
  color: var(--primary);
  font-weight: 700;
}

/* Visual Artwork Showcase & Carousel */
.visual-wrap {
  position: relative;
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 28px;
  background: #FFFFFF;
  box-shadow: var(--shadow-lg);
}

.visual-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  padding: 4px 6px 14px;
}

.window-dots {
  display: flex;
  gap: 6px;
}

.window-dots i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #CBD5E1;
  display: block;
}

.window-dots i:first-child { background: var(--primary); }
.window-dots i:nth-child(2) { background: var(--electric); }
.window-dots i:nth-child(3) { background: var(--cyan); }

.visual-canvas {
  position: relative;
  overflow: hidden;
  aspect-ratio: 1.1 / 1;
  border-radius: 18px;
  background: #F8FAFC;
  border: 1px solid var(--border);
  isolation: isolate;
}

.scene {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  opacity: 0;
  transform: scale(0.95);
  transition: opacity 0.6s ease, transform 0.6s ease;
  pointer-events: none;
}

.scene.active {
  opacity: 1;
  transform: scale(1);
  pointer-events: auto;
}

.scene svg {
  width: 100%;
  height: 100%;
  display: block;
}

.float-tag {
  position: absolute;
  z-index: 10;
  padding: 10px 16px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: var(--shadow-md);
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text);
  backdrop-filter: blur(12px);
  animation: float 5s ease-in-out infinite;
  display: flex;
  align-items: center;
  gap: 8px;
}

.tag-one { left: -16px; top: 22%; }
.tag-two { right: -16px; bottom: 22%; animation-delay: -2.5s; }

.tag-icon {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  background: linear-gradient(135deg, var(--primary), var(--electric));
  color: #FFFFFF;
  border-radius: 6px;
  font-weight: 900;
  font-size: 0.8rem;
}

.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 6px 4px;
}

.carousel-info strong {
  font: 700 1.05rem var(--font-heading);
  display: block;
  color: var(--text);
}

.carousel-info span {
  font-size: 0.78rem;
  color: var(--muted);
}

.carousel-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}

.carousel-progress {
  height: 3px;
  background: var(--border);
  border-radius: 3px;
  margin-top: 10px;
  overflow: hidden;
}

.carousel-progress-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--primary), var(--cyan));
  transition: width 0.3s linear;
}

/* Ticker Banner */
.ticker {
  overflow: hidden;
  border-block: 1px solid var(--border);
  background: var(--panel);
  user-select: none;
}

.ticker-track {
  display: flex;
  align-items: center;
  gap: 32px;
  width: max-content;
  padding: 18px 0;
  animation: ticker 28s linear infinite;
}

.ticker-track span {
  font: 700 0.88rem var(--font-heading);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text);
  white-space: nowrap;
}

.ticker-track b {
  color: var(--primary);
  font-size: 1.1rem;
}

/* Section Utility */
.section {
  padding: 100px 0;
}

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: 48px;
}

.section-head h2 {
  font: 800 clamp(2.4rem, 5vw, 4.2rem) / 1.02 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 14px 0 0;
  color: var(--text);
}

.section-head p {
  max-width: 440px;
  color: var(--muted);
  margin: 0;
  font-size: 1.02rem;
}

/* Services Grid */
.services {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.service {
  position: relative;
  overflow: hidden;
  min-height: 260px;
  padding: 28px;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--card);
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.3s, box-shadow 0.3s;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.service::after {
  content: '';
  position: absolute;
  width: 120px;
  height: 120px;
  right: -60px;
  bottom: -60px;
  border-radius: 50%;
  background: var(--primary);
  filter: blur(45px);
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
}

.service:hover {
  transform: translateY(-8px);
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
}

.service:hover::after {
  opacity: 0.15;
}

.service-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.service-icon {
  width: 50px;
  height: 50px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(79, 70, 229, 0.1), rgba(6, 182, 212, 0.1));
  color: var(--primary);
  font-size: 1.4rem;
  font-weight: 700;
}

.service .number {
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.service h3 {
  font: 700 1.25rem var(--font-heading);
  margin: 24px 0 10px;
  color: var(--text);
}

.service p {
  font-size: 0.88rem;
  color: var(--muted);
  line-height: 1.6;
  margin: 0;
}

/* Portfolio Section */
.work-section {
  background: var(--panel);
  border-block: 1px solid var(--border);
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 32px;
}

.filter {
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 10px 22px;
  background: #FFFFFF;
  color: var(--text);
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 700;
  box-shadow: var(--shadow-sm);
  transition: all 0.25s ease;
}

.filter.active, .filter:hover {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  border-color: transparent;
  color: #FFFFFF;
  box-shadow: 0 6px 20px rgba(79, 70, 229, 0.3);
}

.projects {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.project {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: #FFFFFF;
  box-shadow: var(--shadow-sm);
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.35s, box-shadow 0.35s;
  display: flex;
  flex-direction: column;
}

.project:hover {
  transform: translateY(-7px);
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
}

.project[hidden] {
  display: none !important;
}

.project-art {
  position: relative;
  overflow: hidden;
  aspect-ratio: 1.45 / 1;
  background: #F8FAFC;
  width: 100%;
  height: 100%;
}

.project-art svg {
  width: 100%;
  height: 100%;
  display: block;
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.project:hover .project-art svg {
  transform: scale(1.05);
}

.concept-badge {
  position: absolute;
  bottom: 14px;
  left: 14px;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.15em;
  color: var(--primary);
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 10px;
  backdrop-filter: blur(8px);
  box-shadow: var(--shadow-sm);
}

.project-info {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 20px 22px;
  background: #FFFFFF;
  margin-top: auto;
}

.project-info h3 {
  font: 700 1.15rem var(--font-heading);
  margin: 0;
  color: var(--text);
}

.project-info p {
  color: var(--muted);
  font-size: 0.8rem;
  margin: 4px 0 0;
}

.project-link {
  width: 38px;
  height: 38px;
  border: 1px solid var(--border);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--primary);
  flex-shrink: 0;
  transition: all 0.2s;
}

.project:hover .project-link {
  background: var(--primary);
  color: #FFFFFF;
  border-color: var(--primary);
}

/* Motion Lab Section */
.feature {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  padding: 56px;
  border: 1px solid var(--border);
  border-radius: 28px;
  background: radial-gradient(ellipse at 90% 30%, rgba(79, 70, 229, 0.08), transparent 50%), #F5F8FF;
  overflow: hidden;
  position: relative;
  box-shadow: var(--shadow-sm);
}

.feature h2 {
  font: 800 clamp(2.5rem, 5vw, 4.4rem) / 1 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 16px 0 20px;
  color: var(--text);
}

.feature p {
  color: var(--muted);
  max-width: 480px;
  font-size: 1.05rem;
  margin-bottom: 32px;
}

.feature-art {
  position: relative;
  min-height: 320px;
  display: grid;
  place-items: center;
}

.orb {
  width: 190px;
  height: 190px;
  border-radius: 40%;
  background: linear-gradient(140deg, #4F46E5 0%, #2563EB 35%, #06B6D4 70%, #8B5CF6 100%);
  box-shadow: inset -15px -15px 35px rgba(255, 255, 255, 0.4), 0 12px 40px rgba(79, 70, 229, 0.25);
  transform: rotate(25deg);
  animation: float 6s ease-in-out infinite;
}

.orb-ring {
  position: absolute;
  width: 300px;
  height: 120px;
  border: 2px solid rgba(79, 70, 229, 0.4);
  border-radius: 50%;
  transform: rotate(-28deg);
  animation: spin 24s linear infinite;
}

.orb-ring.two {
  width: 320px;
  height: 140px;
  transform: rotate(55deg);
  border-color: rgba(6, 182, 212, 0.4);
  animation-direction: reverse;
}

/* About Mukesh Singh */
.about-grid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 56px;
  align-items: center;
}

.about-art {
  min-height: 400px;
  position: relative;
  display: grid;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 24px;
  background: radial-gradient(circle at 50% 40%, rgba(79, 70, 229, 0.1), transparent 60%), #F5F8FF;
  overflow: hidden;
}

.about-art::before {
  content: 'MUKESH SINGH / CREATIVE DIRECTOR';
  position: absolute;
  bottom: 22px;
  left: 22px;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--muted);
}

.monogram {
  font: 900 clamp(7rem, 16vw, 13rem) / 1 var(--font-heading);
  letter-spacing: -0.12em;
  color: transparent;
  -webkit-text-stroke: 2px var(--primary);
  text-shadow: 10px 10px 0 rgba(79, 70, 229, 0.12);
  transform: rotate(-6deg);
  user-select: none;
}

.about-copy h2 {
  font: 800 clamp(2.5rem, 5vw, 4.2rem) / 1.02 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 16px 0;
  color: var(--text);
}

.about-copy p {
  color: var(--muted);
  font-size: 1.05rem;
  margin-bottom: 16px;
}

.skills {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 28px 0 32px;
}

.skills span {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 8px 16px;
  color: var(--text);
  font-size: 0.82rem;
  font-weight: 700;
  background: #FFFFFF;
  box-shadow: var(--shadow-sm);
}

/* Contact Section & Footer */
.contact {
  padding: 110px 0;
  text-align: center;
  background: radial-gradient(ellipse at 50% 100%, rgba(79, 70, 229, 0.08), transparent 65%), #FFFFFF;
}

.contact h2 {
  font: 800 clamp(2.8rem, 7vw, 5.8rem) / 0.98 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 20px 0;
  color: var(--text);
}

.contact p {
  max-width: 580px;
  margin: 0 auto 32px;
  color: var(--muted);
  font-size: 1.08rem;
}

.contact-actions {
  display: flex;
  justify-content: center;
  gap: 14px;
  flex-wrap: wrap;
}

.footer {
  border-top: 1px solid var(--border);
  padding: 32px 0;
  color: var(--muted);
  font-size: 0.85rem;
  background: #F8FAFC;
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.socials {
  display: flex;
  gap: 10px;
}

/* Reveal animation */
.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.7s cubic-bezier(0.16, 1, 0.3, 1), transform 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

.blogger-hidden {
  display: none !important;
}

/* Animations */
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-14px); }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@keyframes ticker {
  to { transform: translateX(-50%); }
}

/* Responsive Design */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .hero-copy {
    text-align: center;
  }
  .hero-copy p {
    margin-inline: auto;
  }
  .hero-actions, .hero-meta {
    justify-content: center;
  }
  .visual-wrap {
    width: min(100%, 680px);
    margin: auto;
  }
  .services {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .projects {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .about-grid {
    gap: 36px;
  }
  .feature {
    gap: 24px;
    padding: 40px;
  }
}

@media (max-width: 768px) {
  .container {
    width: calc(100% - 32px);
  }
  .nav {
    height: 70px;
  }
  .menu-toggle {
    display: inline-flex !important;
  }
  .navlinks {
    display: none;
    position: absolute;
    left: 0;
    right: 0;
    top: 70px;
    padding: 24px;
    background: #FFFFFF;
    border-bottom: 1px solid var(--border);
    flex-direction: column;
    align-items: stretch;
    gap: 18px;
    box-shadow: var(--shadow-lg);
  }
  .navlinks.open {
    display: flex;
  }
  .navlinks .navcta {
    text-align: center;
  }
  .hero {
    padding: 56px 0 48px;
  }
  .hero-copy h2 {
    font-size: clamp(2.8rem, 11vw, 4.4rem);
  }
  .visual-wrap {
    padding: 12px;
    border-radius: 20px;
  }
  .float-tag {
    font-size: 0.68rem;
    padding: 8px 12px;
  }
  .tag-one { left: -6px; }
  .tag-two { right: -6px; }
  .section {
    padding: 70px 0;
  }
  .section-head {
    display: block;
    margin-bottom: 32px;
  }
  .section-head p {
    margin-top: 14px;
  }
  .services {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .service {
    padding: 20px;
    min-height: auto;
  }
  .projects {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .feature {
    grid-template-columns: 1fr;
    padding: 32px 24px;
    gap: 12px;
  }
  .feature-art {
    min-height: 240px;
    grid-row: 1;
  }
  .orb { width: 140px; height: 140px; }
  .orb-ring { width: 230px; height: 95px; }
  .orb-ring.two { width: 250px; height: 110px; }
  .about-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }
  .about-art { min-height: 280px; }
  .monogram { font-size: 8.5rem; }
  .contact { padding: 75px 0; }
  .footer-inner {
    flex-direction: column;
    text-align: center;
  }
  .socials {
    justify-content: center;
  }
}

@media (max-width: 390px) {
  .container {
    width: calc(100% - 24px);
  }
  .brand { font-size: 0.98rem; }
  .brand-icon { width: 34px; height: 34px; font-size: 1.1rem; }
  .hero-copy h2 { font-size: 2.6rem; }
  .hero-actions .btn { width: 100%; }
  .carousel-nav { flex-direction: column; align-items: flex-start; gap: 8px; }
  .intro h1 { font-size: 2.2rem; }
  .intro .btn { width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
  .reveal {
    opacity: 1;
    transform: none;
  }
}

body.script:
//
(function(){
// Cinematic Intro Screen handling
  var intro = document.getElementById('introScreen');
  var enterBtn = document.getElementById('enterStudio');
var isTransitioning = false;

function startCinematicTransition() {
  if (isTransitioning) return;
  isTransitioning = true;

  if (enterBtn) {
    enterBtn.classList.add('active-cta');
  }

  if (intro) {
    intro.classList.add('transitioning');
  }

    try { sessionStorage.setItem('scs-intro-seen', '1'); } catch(e) {}

  var prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var duration = prefersReducedMotion ? 200 : 950;

  var safetyTimer = setTimeout(finishTransition, duration + 150);

  function finishTransition() {
    clearTimeout(safetyTimer);
    if (intro) {
      intro.classList.add('hidden');
      intro.classList.remove('transitioning');
    }
    document.body.classList.add('intro-dismissed');
    document.body.style.overflow = '';
  }

  setTimeout(finishTransition, duration);
  }

  try {
    if (sessionStorage.getItem('scs-intro-seen') === '1' && intro) {
      intro.classList.add('hidden');
    document.body.classList.add('intro-dismissed');
    document.body.style.overflow = '';
  } else {
    document.body.style.overflow = 'hidden';
    }
} catch(e) {
  document.body.style.overflow = '';
}

  if (enterBtn) {
  enterBtn.addEventListener('click', function(e) {
    e.preventDefault();
    startCinematicTransition();
  });
  }

  // Mobile Navigation Toggle
  var menuBtn = document.getElementById('menuToggle');
  var navLinks = document.getElementById('navLinks');

  if (menuBtn && navLinks) {
    menuBtn.addEventListener('click', function(){
      var isOpen = navLinks.classList.toggle('open');
      menuBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });

    navLinks.querySelectorAll('a').forEach(function(link){
      link.addEventListener('click', function(){
        navLinks.classList.remove('open');
        menuBtn.setAttribute('aria-expanded', 'false');
      });
    });
  }

  // Automatic Visual Carousel
  var scenes = [].slice.call(document.querySelectorAll('.scene'));
  var carouselTitle = document.getElementById('carouselTitle');
  var carouselSub = document.getElementById('carouselSub');
  var carouselProgress = document.getElementById('carouselProgress');
  var btnPrev = document.getElementById('carouselPrev');
  var btnNext = document.getElementById('carouselNext');
  var btnToggle = document.getElementById('carouselToggle');
  var togglePauseIcon = document.getElementById('togglePauseIcon');

  var curIdx = 0;
  var timer = null;
  var isPaused = false;
  var intervalMs = 4000;
  var prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function setProgress(percent) {
    if (carouselProgress) {
      carouselProgress.style.width = percent + '%';
    }
  }

  function showSlide(idx) {
    if (!scenes.length) return;
    curIdx = (idx + scenes.length) % scenes.length;
    scenes.forEach(function(s, i) {
      s.classList.toggle('active', i === curIdx);
    });

    var activeScene = scenes[curIdx];
    if (activeScene) {
      if (carouselTitle) carouselTitle.textContent = activeScene.getAttribute('data-title') || '';
      if (carouselSub) carouselSub.textContent = activeScene.getAttribute('data-sub') || '';
    }

    setProgress(((curIdx + 1) / scenes.length) * 100);
  }

  function startCarousel() {
    stopCarousel();
    if (!isPaused && !prefersReducedMotion && !document.hidden) {
      timer = setInterval(function(){
        showSlide(curIdx + 1);
      }, intervalMs);
    }
  }

  function stopCarousel() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  }

  if (scenes.length) {
    showSlide(0);
    startCarousel();

    if (btnPrev) {
      btnPrev.addEventListener('click', function(){
        showSlide(curIdx - 1);
        startCarousel();
      });
    }

    if (btnNext) {
      btnNext.addEventListener('click', function(){
        showSlide(curIdx + 1);
        startCarousel();
      });
    }

    if (btnToggle) {
      btnToggle.addEventListener('click', function(){
        isPaused = !isPaused;
        btnToggle.setAttribute('aria-label', isPaused ? 'Play carousel' : 'Pause carousel');
        if (togglePauseIcon) {
          togglePauseIcon.innerHTML = isPaused ?
            "<polygon points='5 3 19 12 5 21 5 3'/>" :
            "<rect x='6' y='4' width='4' height='16'/><rect x='14' y='4' width='4' height='16'/>";
        }
        if (isPaused) stopCarousel();
        else startCarousel();
      });
    }

    var visualCanvas = document.getElementById('visualCanvas');
    if (visualCanvas) {
      visualCanvas.addEventListener('mouseenter', stopCarousel);
      visualCanvas.addEventListener('mouseleave', function(){
        if (!isPaused) startCarousel();
      });

      var touchStartX = 0;
      visualCanvas.addEventListener('touchstart', function(e){
        if (e.touches.length) touchStartX = e.touches[0].clientX;
      }, {passive: true});

      visualCanvas.addEventListener('touchend', function(e){
        if (e.changedTouches.length) {
          var diff = e.changedTouches[0].clientX - touchStartX;
          if (Math.abs(diff) > 40) {
            showSlide(curIdx + (diff < 0 ? 1 : -1));
            startCarousel();
          }
        }
      }, {passive: true});
    }

    document.addEventListener('visibilitychange', function(){
      if (document.hidden) stopCarousel();
      else if (!isPaused) startCarousel();
    });
  }

  // Portfolio Filter handling
  var filterButtons = document.querySelectorAll('.filter');
  var projectCards = document.querySelectorAll('.project');

  filterButtons.forEach(function(btn){
    btn.addEventListener('click', function(){
      var filterValue = btn.getAttribute('data-filter');

      filterButtons.forEach(function(b){ b.classList.remove('active'); });
      btn.classList.add('active');

      projectCards.forEach(function(card){
        var tags = (card.getAttribute('data-tags') || '').split(' ');
        if (filterValue === 'all' || tags.indexOf(filterValue) !== -1) {
          card.removeAttribute('hidden');
        } else {
          card.setAttribute('hidden', 'hidden');
        }
      });
    });
  });

  // Intersection Observer for Section Reveals
  if ('IntersectionObserver' in window) {
    var observer = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting) {
          e.target.classList.add('visible');
          observer.unobserve(e.target);
        }
      });
    }, { threshold: 0.1 });

    document.querySelectorAll('.reveal').forEach(function(el){
      observer.observe(el);
    });
  } else {
    document.querySelectorAll('.reveal').forEach(function(el){
      el.classList.add('visible');
    });
  }

  if (prefersReducedMotion) {
    document.querySelectorAll('.reveal').forEach(function(el){
      el.classList.add('visible');
    });
  }

  // Dynamic Year
  var yearEl = document.getElementById('yearNow');
  if (yearEl) {
    yearEl.textContent = new Date().getFullYear();
  }
})();
//
